      try {
        var o = new Intl.DateTimeFormat('en-GB', { timeZone: fus, timeZoneName: 'longOffset' }).formatToParts(acum).filter(function (x) { return x.type === 'timeZoneName'; })[0].value;
        var m = /GMT([+-]\d{2}:\d{2})/.exec(o); if (m) offset = m[1];
